import * as AasTypes from "../src/types";
import * as AasVerification from "../src/verification";

test("setText", () => {
  const item = new AasTypes.Item("a", ["b"]);
  AasVerification.setText(item, "x");
  expect(item.text).toBe("x");
});

test("setMaybeText", () => {
  const item = new AasTypes.Item("a", []);
  AasVerification.setMaybeText(item, "x");
  expect(item.maybeText).toBe("x");
});

test("copyMaybeTextAndSetMaybeKind", () => {
  const item = new AasTypes.Item("a", [], "old");
  const other = new AasTypes.Item("b", []);
  AasVerification.copyMaybeTextAndSetMaybeKind(item, other);
  expect(item.maybeText).toBeNull();
  expect(item.maybeKind).toBe(AasTypes.Kind.Alpha);
});

test("setTextThroughAlias", () => {
  const item = new AasTypes.Item("a", []);
  AasVerification.setTextThroughAlias(item, "x");
  expect(item.text).toBe("x");
});

test("setTexts", () => {
  const item = new AasTypes.Item("a", ["b"]);
  const texts = ["x", "y"];
  AasVerification.setTexts(item, texts);
  expect(item.texts).toBe(texts);
});

test("setFirstAndLastText", () => {
  const item = new AasTypes.Item("a", ["a", "b", "c"]);
  AasVerification.setFirstAndLastText(item, "x");
  expect(item.texts).toStrictEqual(["x", "b", "x"]);
});

test("setTextThroughListAlias", () => {
  const item = new AasTypes.Item("a", ["a", "b", "c"]);
  AasVerification.setTextThroughListAlias(item, "x");
  expect(item.texts).toStrictEqual(["a", "x", "c"]);
});

test("setNumbers", () => {
  const numbers = [1, 2, 3, 4];
  AasVerification.setNumbers(numbers, 10);
  expect(numbers).toStrictEqual([10, 2, 5, 4]);
});

test("setNumbers with an index out of range", () => {
  const numbers = [1];
  expect(() => AasVerification.setNumbers(numbers, 10)).toThrow(RangeError);
  expect(numbers.length).toBe(1);
});

test("setNestedText", () => {
  const items = [
    new AasTypes.Item("a", ["a", "b"]),
    new AasTypes.Item("b", ["c"])
  ];
  AasVerification.setNestedText(items, "x");
  expect(items[0].texts).toStrictEqual(["a", "x"]);
  expect(items[1].text).toBe("x");
});

test("replaceFirstItem", () => {
  const items = [
    new AasTypes.Item("a", []),
    new AasTypes.Item("b", [])
  ];
  const item = new AasTypes.Item("c", []);
  AasVerification.replaceFirstItem(items, item);
  expect(items[0]).toBe(item);
  expect(items.length).toBe(2);
});

test("setTextsInLoops", () => {
  const items = [
    new AasTypes.Item("a", ["a"]),
    new AasTypes.Item("b", ["b", "c"])
  ];
  AasVerification.setTextsInLoops(items, "x");
  for (const item of items) {
    expect(item.text).toBe("x");
    expect(item.texts[0]).toBe("x");
  }
});

